  ('8b447cc1-0fde-43f3-bb2f-58d7749bb0c9', 'a9b0c1d2-3e4f-4a86-9b56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Speaking, listening, and oral language', 'Recognize oral language as the foundation for reading comprehension, writing, vocabulary, and classroom participation. Core emphasis: Academic talk, listening routines, discussion, storytelling, language development, presentation, and collaborative conversation.', 8),
