  ('27e67dab-40d2-4b21-86c9-7d21d197ec27', 'a9b0c1d2-3e4f-4a86-9b56-6d7e8f9a0b66', '825dea3c-9494-456d-afea-3e6515a8e61c', 'concept'::public.curated_course_node_type, 'Collaborative norms', null, 2),
  ('2ae60bce-0442-4758-bc7f-29f37243c944', 'a9b0c1d2-3e4f-4a86-9b56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Literacy assessment', 'Prepare teachers to use screening, diagnostic, formative, summative, and performance assessments responsibly. Core emphasis: Screeners, diagnostics, running records, phonics inventories, writing rubrics, comprehension checks, validity, fairness, and data use.', 9),
  ('e51e1486-db11-4b20-b496-25bda8590be1', 'a9b0c1d2-3e4f-4a86-9b56-6d7e8f9a0b66', '2ae60bce-0442-4758-bc7f-29f37243c944', 'subtopic'::public.curated_course_node_type, 'Assessment purposes', 'Different assessments answer different instructional questions.', 0),
  ('55aae044-06ec-454e-8532-cbe782d4c60a', 'a9b0c1d2-3e4f-4a86-9b56-6d7e8f9a0b66', 'e51e1486-db11-4b20-b496-25bda8590be1', 'concept'::public.curated_course_node_type, 'Screening', null, 0),
