  ('75b2c79d-ced3-4f4a-9d1a-d9f80077b90d', 'a9b0c1d2-3e4f-4a86-9b56-6d7e8f9a0b66', 'ecb809b3-5660-4479-bae5-a707838419f7', 'subtopic'::public.curated_course_node_type, 'Multilingual literacy development', 'Students learn that multilingualism is an asset, not a deficit.', 0),
