cept", "title": "Goal setting"}], "description": "Conferences make feedback individualized and actionable."}, {"id": "698689af-e06c-43d2-806f-643bd90c57a9", "type": "subtopic", "title": "Mentor texts", "children": [{"id": "2034eea5-115e-44f5-adc7-ee24c2e48fb3", "type": "concept", "title": "Sentence craft"}, {"id": "1ae42f73-bf5a-4829-919b-cca6a3d7514e", "type": "concept", "title": "Structure imitation"}, {"id": "2ba51969-fdf3-4a2a-8d6c-666e7d99fe97", "type": "concept", "title": "Author study"}], "description": "Published texts show craft moves students can try."}]}, {"id": "1793b1b0-8775-46dc-8d48-19bbd20e21bf", "type": "topic", "title": "Genre study: narrative, informational, and opinion writing", "description": "Help students teach how genre shapes reading, writing, structure, evidence, and audience. Core emphasis: Narrative, informational, opinion/argument, genre features, mentor texts, rubrics, and cross-curricular writing.", "children": [{"id": "fb8f82f8-11e9-42c0-9a9b-339eecdc4e1d", "type": "subtopic", "title": "Narrative writing", "children": [{"id": "6f7c32ef-697a-43bc-a210-407c4f296e92", "type": "concept", "title": "Story structure"}, {"id": "168b5b5e-724f-4bb7-be71-33884ae97bab", "type": "concept", "title": "Dialogue and description"}, {"id": "39f4f85f-dab8-41a1-a9a2-a98563b8cddc", "type": "concept", "title": "Personal narrative"}], "description": "Narratives teach sequence, character, event, voice, and elaboration."}, {"id": "41508629-3e33-4d2f-a37c-1b3a304cd7a4", "type": "subtopic", "title": "Informational writing", "children": [{"id": "db75fd96-1913-46b5-a81b-78dec16c8d2c", "type": "concept", "title": "Main ideas"}, {"id": "ee8080f7-ce2c-474d-8394-d8077f92f173", "type": "concept", "title": "Text features"}, {"id": "eaeb2402-46ae-41dd-8c65-4415243b60c1", "type": "concept", "title": "Domain vocabulary"}], "description": "Informational writing builds explanation and knowledge communication."}, {"id": "a710b642-83d0-40e7-80cb-e2f2e6f8f274", "type": "subtopic", "title": "Opinion and argument writing", "children": [{"id": "91703c10-652b-41bf-99b7-3b8d5e362068", "type": "concept", "title": "Claims"}, {"id": "d4362337-dd10-4a7c-ac7c-f2407a3867fc", "type": "concept", "title": "Reasons and evidence"}, {"id": "e65dbfc1-cadc-4dfa-8082-af02be10cdfa", "type": "concept", "title": "Counterargument readiness"}], "description": "Opinion writing introduces claims, reasons, evidence, and audience."}, {"id": "a07dac23-9a2e-4f19-977c-ef43ee00675a", "type": "subtopic", "title": "Genre-based assessment", "children": [{"id": "f5404145-f236-4007-9b4f-1cd4ca2757aa", "type": "concept", "title": "Trait rubrics"}, {"id": "4636bc2b-b051-4cdf-9f14-e57cd4e2dab7", "type": "concept", "title": "Anchor papers"}, {"id": "b84d36b8-2032-4f6d-bf0f-c03ec8c37455", "type": "concept", "title": "Revision goals"}], "description": "Genre expectations should be visible in rubrics and feedback."}]}, {"id": "321ea302-5928-4bca-8884-a978c8b195d2", "type": "topic", "title": "Grammar, syntax, and conventions instruction", "description": "Teach conventions as tools for meaning, clarity, voice, and access rather than isolated correction. Core emphasis: Sentence structure, grammar, punctuation, capitalization, usage, syntax, morphology, and editing routines.", "children": [{"id": "d47e21e6-b32f-4b5f-a744-88b46b9f8afe", "type": "subtopic", "title": "Sentence-level instruction", "children": [{"id": "a4c4099d-640b-40e8-b9b4-1212c9870398", "type": "concept", "title": "Subjects and predicates"}, {"id": "0e8ab033-81c1-48e4-815c-2414908dfb49", "type": "concept", "title": "Sentence combining"}, {"id": "519d228e-8063-4460-8ca4-13501316d8ae", "type": "concept", "title": "Complex sentences"}], "description": "Students learn grammar by studying how sentences make meaning."}, {"id": "2b2c6323-7be0-4c52-9c34-813eb480b258", "type": "subtopic", "title": "Conventions in context", "children": [{"id": "2226ee26-7c17-4aec-9ae8-ffc281d55ac5", "type": "concept", "title": "Punctuation for meaning"}, {"id": "d1f79ae0-e297-4ad8-95e6-7ef8b4acfc57", "type": "concept", "title": "Capitalization"}, {"id": "eb2a6aca-a432-4824-9843-505b75e73a95", "type": "concept", "title": "Editing checklists"}], "description": "Conventions instruction works best inside reading and writing."}, {"id": "ae49df68-ae32-4065-9140-a722f792dc64", "type": "subtopic", "title": "Syntax and comprehension", "children": [{"id": "44dc9955-39cb-418e-9c00-3162dba3ea81", "type": "concept", "title": "Clause structures"}, {"id": "fdd01c26-3957-4d47-8e45-15d83925623c", "type": "concept", "title": "Connectives"}, {"id": "f25ee8ae-10d2-474e-aa8c-269d0d5266d8", "type": "concept", "title": "Deconstructing sentences"}], "description": "Complex syntax affects reading comprehension and academic language."}, {"id": "a709fe7b-a2a1-4fde-819e-dce3fdcf58a3", "type": "subtopic", "title": "Language variation and standard English", "children": [{"id": "3ebfb781-14a0-42e9-9d90-75daab99c322", "type": "concept", "title": "Code-switching/code-meshing"}, {"id": "ce665d2d-22ec-4237-9e26-9bcece606770", "type": "concept", "title": "Dialect awareness"}, {"id": "63a5067d-da37-45eb-b8d5-b37601ab63fe", "type": "concept", "title": "Audience and purpose"}], "description": "Teachers honor dialects while teaching access to academic conventions."}]}, {"id": "f4ffe9b5-f39b-4b70-bc6b-82d308264db9", "type": "topic", "title": "Word study, spelling, and vocabulary development", "description": "Connect spelling, morphology, phonics, and vocabulary into a coherent word-learning system. Core emphasis: Developmental spelling, morphology, etymology, academic vocabulary, semantic networks, and word-learning routines.", "children": [{"id": "e6658141-b275-4e99-aa29-1a0b76515069", "type": "subtopic", "title": "Developmental spelling", "children": [{"id": "52faf234-7a26-4fa6-a9b2-cc2b377378dc", "type": "concept", "title": "Invented spelling analysis"}, {"id": "9d1e2a10-d758-4269-9b57-cb5dd4825ff4", "type": "concept", "title": "Word sorts"}, {"id": "5b4c2b5a-eee1-4622-9a90-22d064651155", "type": "concept", "title": "Spelling stages"}], "description": "Spelling reveals what students understand about sounds and patterns."}, {"id": "853b3011-e1ac-4b48-9791-c18f47462773", "type": "subtopic", "title": "Morphology", "children": [{"id": "a6a3805c-3307-40da-81d8-079d5cfb062d", "type": "concept", "title": "Prefixes"}, {"id": "79ab8ddc-0d24-4ca4-94d6-289d004742ca", "type": "concept", "title": "Suffixes"}, {"id": "09f80804-13ef-4ef7-a832-f7d2f615af28", "type": "concept", "title": "Roots and bases"}], "description": "Morphemes help students decode, spell, and understand complex words."}, {"id": "2852ee08-8ab4-4538-9565-a4121d69cce5", "type": "subtopic", "title": "Vocabulary instruction", "children": [{"id": "d34e3f97-88a0-4513-88b0-a0719d5d75e3", "type": "concept", "title": "Tiered vocabulary"}, {"id": "6b8d422f-bf06-46f1-bd52-167a2c560dbb", "type": "concept", "title": "Student-friendly definitions"}, {"id": "979e214f-9331-4e40-a463-c877c8a7eb43", "type": "concept", "title": "Multiple encounters"}], "description": "Vocabulary grows through explicit teaching and rich exposure."}, {"id": "e414c3a6-99f7-49b9-aed5-98f9916167cb", "type": "subtopic", "title": "Word consciousness", "children": [{"id": "52c6adc5-558f-4fd7-8baa-496d28c45bc5", "type": "concept", "title": "Etymology"}, {"id": "25eb88e7-6711-49b1-8e5d-aedad12d7dc9", "type": "concept", "title": "Word families"}, {"id": "536852de-10e3-4d48-a39e-afdd96deb71c", "type": "concept", "title": "Context clues"}], "description": "Students become curious about how words work."}]}, {"id": "8b447cc1-0fde-43f3-bb2f-58d7749bb0c9", "type": "topic", "title": "Speaking, listening, and oral language", "description": "Recognize oral language as the foundation for reading comprehension, writing, vocabulary, and classroom participation. Core emphasis: Academic talk, listening routines, discussion, storytelling, language development, presentation, and collaborative conversation.", "children": [{"id": "0014454b-cac4-4612-9c6a-89e1812288ef", "type": "subtopic", "title": "Oral language development", "children": [{"id": "cbf7a13e-2675-4767-9f03-ceb38387820b", "type": "concept", "title": "Syntax growth"}, {"id": "0eeebb48-7772-455b-b794-2e84f3ef1af7", "type": "concept", "title": "Vocabulary depth"}, {"id": "5a31305a-dd39-4760-bac7-ef8fdb09dceb", "type": "concept", "title": "Narrative language"}], "description": "Students learn why talk is not extra; it is literacy infrastructure."}, {"id": "9da716f3-d4a2-4047-ba96-900250d2e9a6", "type": "subtopic", "title": "Academic discussion", "children": [{"id": "5eb7d5ad-7656-4d7c-aa10-ce8336447fe2", "type": "concept", "title": "Accountable talk"}, {"id": "8161b7ba-4987-42a6-9429-f954797ebf95", "type": "concept", "title": "Turn-taking"}, {"id": "0ae5dd10-dec5-42d6-b9f2-24178d5590a5", "type": "concept", "title": "Text-based discussion"}], "description": "Discussion builds comprehension, evidence use, and reasoning."}, {"id": "4c77938c-d80a-4506-bd65-a86fe4015fd6", "type": "subtopic", "title": "Listening comprehension", "children": [{"id": "274fc6d9-3623-4488-93d2-209a946e8079", "type": "concept", "title": "Interactive read-alouds"}, {"id": "880a49fe-e91d-4b02-90f8-8e53e1eb977c", "type": "concept", "title": "Retelling"}, {"id": "8625d434-342c-44a9-b3df-ee121947cd59", "type": "concept", "title": "Question generation"}], "description": "Listening supports knowledge building before students can read all texts independently."}, {"id": "825dea3c-9494-456d-afea-3e6515a8e61c", "type": "subtopic", "title": "Presentation and collaboration", "children": [{"id": "b451cdf7-7225-4827-bd86-31210a72e7b5", "type": "concept", "title": "Oral presentations"}, {"id": "946e471d-3725-4ebc-9b3c-c2e7e56af2f8", "type": "concept", "title": "Peer response"}, {"id": "27e67dab-40d2-4b21-86c9-7d21d197ec27", "type": "concept", "title": "Collaborative norms"}], "description": "Language arts includes speaking clearly and listening respectfully."}]}, {"id": "2ae60bce-0442-4758-bc7f-29f37243c944", "type": "topic", "title": "Literacy assessment", "description": "Prepare teachers to use screening, diagnostic, formative, summative, and performance assessments responsibly. Core emphasis: Screeners, diagnostics, running records, phonics inventories, writing rubrics, comprehension checks, validity, fairness, and data use.", "children": [{"id": "e51e1486-db11-4b20-b496-25bda8590be1", "type": "subtopic", "title": "Assessment purposes", "children": [{"id": "55aae044-06ec-454e-8532-cbe782d4c60a", "type": "concept", "title": "Screening"}, {"id": "28e37f9f-450d-4b14-9393-ff80d4679580", "type": "concept", "title": "Diagnosis"}, {"id": "457db925-fbc4-4777-a440-a8a29cbe6750", "type": "concept", "title": "Progress monitoring"}], "description": "Different assessments answer different instructional questions."}, {"id": "73e60dcf-9b82-4df9-b42d-076bad01e8d6", "type": "subtopic", "title": "Foundational skill assessment", "children": [{"id": "ae144fad-6bdd-4ed1-baff-cf736e563e1c", "type": "concept", "title": "Phonemic awareness checks"}, {"id": "e97f552a-30e5-4c81-93b9-40057e1b2b24", "type": "concept", "title": "Phonics inventories"}, {"id": "3ab79350-eb06-40c5-ba92-1d90a5a6c5b5", "type": "concept", "title": "Oral reading fluency"}], "description": "Teachers need precise data on decoding and word-reading skills."}, {"id": "9e46364d-7b06-49af-8a43-5729e9ae4354", "type": "subtopic", "title": "Comprehension and writing assessment", "children": [{"id": "7b61151d-1b8f-44bc-a2c7-3692a8d136c7", "type": "concept", "title": "Retellings"}, {"id": "b33aa1d9-0983-4f20-a9e4-98a015598466", "type": "concept", "title": "Written responses"}, {"id": "048b9630-85bd-4a9e-b1de-fb2392e5ea02", "type": "concept", "title": "Writing rubrics"}], "description": "Higher-level literacy needs multiple forms of evidence."}, {"id": "37358f31-2838-4158-a07f-1d321d84e8c5", "type": "subtopic", "title": "Fairness and interpretation", "children": [{"id": "fbae5293-168f-4d1c-ad65-2d220a5533d6", "type": "concept", "title": "Validity"}, {"id": "7a53b545-e381-4a80-8db6-f2cb66b91cd0", "type": "concept", "title": "Bias"}, {"id": "a810fbc6-3cb5-49a5-93be-b342776b3f1f", "type": "concept", "title": "Accommodations"}], "description": "Assessment must avoid overclaiming and account for language and disability."}]}, {"id": "513907fd-c6e5-458f-b8da-42b0a9cfdb4d", "type": "topic", "title": "Supporting struggling readers and writers", "description": "Use evidence-based intervention, differentiation, and progress monitoring to support students before gaps widen. Core emphasis: MTSS, dyslexia, intervention cycles, explicit instruction, scaffolds, accommodations, and family collaboration.", "children": [{"id": "79a455bc-39b1-4f18-a94e-69bb4936efe2", "type": "subtopic", "title": "MTSS and intervention cycles", "children": [{"id": "73897e5a-2eac-40a6-8def-b54299a2b7c6", "type": "concept", "title": "Tier 1/2/3"}, {"id": "ba42d368-d764-42bc-888e-409f3c75409d", "type": "concept", "title": "Intervention dosage"}, {"id": "6daf7007-a1e9-46cc-ad27-0fcd266d74ef", "type": "concept", "title": "Decision rules"}], "description": "Support should be systematic, timely, and data-informed."}, {"id": "0fec732c-6b5a-445d-ba99-385119dc53ef", "type": "subtopic", "title": "Dyslexia and reading difficulties", "children": [{"id": "d3de1b33-4f2c-429c-94ea-0244c17eff87", "type": "concept", "title": "Phonological deficits"}, {"id": "70b67aca-4a25-4d51-9e6d-42fbafc7e7ed", "type": "concept", "title": "Rapid naming"}, {"id": "bbab0a25-5af0-4043-aa06-37146a7a7235", "type": "concept", "title": "Structured literacy intervention"}], "description": "Teachers learn warning signs and evidence-based instructional responses."}, {"id": "39ca55c6-8da1-454e-83a8-26097ca60c15", "type": "subtopic", "title": "Writing difficulties", "children": [{"id": "f54e8110-eed2-44fd-9f38-0e819532d4b4", "type": "concept", "title": "Sentence frames"}, {"id": "7eb72f43-693c-4586-9712-ee58d48e5145", "type": "concept", "title": "Strategy instruction"}, {"id": "675162a1-4e37-466f-aec9-0b941d71ddec", "type": "concept", "title": "Assistive technology"}], "description": "Struggling writers need explicit support for planning, transcription, and revision."}, {"id": "d5419ac0-2caf-4166-80d7-f7d812b69bf4", "type": "subtopic", "title": "Progress monitoring and collaboration", "children": [{"id": "cf4c16e9-d436-4cbd-8e77-d7c42a6ef0f2", "type": "concept", "title": "Curriculum-based measures"}, {"id": "ccdb5ad0-8545-4e86-92ec-83bb3b4640f1", "type": "concept", "title": "Family communication"}, {"id": "13c08821-078b-4e47-9a6b-63ffa4cfd3b3", "type": "concept", "title": "Specialist collaboration"}], "description": "Intervention improves when teachers track growth and collaborate."}]}, {"id": "ecb809b3-5660-4479-bae5-a707838419f7", "type": "topic", "title": "Culturally responsive, multilingual, and inclusive literacy", "description": "Make literacy instruction responsive to students' languages, identities, cultures, abilities, and funds of knowledge. Core emphasis: Multilingual learners, translanguaging, culturally sustaining pedagogy, accessible texts, UDL, family engagement, and disability-inclusive instruction.", "children": [{"id": "75b2c79d-ced3-4f4a-9d1a-d9f80077b90d", "type": "subtopic", "title": "Multilingual literacy development", "children": [{"id": "71cbdfcb-a39c-4ed4-90c7-3bed06d5c561", "type": "concept", "title": "Transfer across languages"}, {"id": "3bea02d1-f946-469a-aaaf-fdab302c2e09", "type": "concept", "title": "Oral language scaffolds"}, {"id": "9d3539fe-0bb8-45b5-b962-ff8da446c323", "type": "concept", "title": "Home-language resources"}], "description": "Students learn that multilingualism is an asset, not a deficit."}, {"id": "285168e0-65b0-4231-bcaf-96b94dc57f67", "type": "subtopic", "title": "Culturally sustaining texts", "children": [{"id": "1886f1d3-6b06-4c67-8a1e-0c9fff4a751e", "type": "concept", "title": "Text diversity"}, {"id": "fbf80b8b-48b8-4944-9164-18d66f2db2da", "type": "concept", "title": "Identity and representation"}, {"id": "ac405455-2358-4c99-a0f3-72e058211c04", "type": "concept", "title": "Critical literacy"}], "description": "Text choices should reflect students and expand their worlds."}, {"id": "058c7de9-236a-4414-b346-abe9d39a3ba1", "type": "subtopic", "title": "Universal Design for Learning", "children": [{"id": "2a0fd857-3e2e-4c02-ad3f-73a2a356e646", "type": "concept", "title": "Multiple means of representation"}, {"id": "d16840eb-c4d4-4f6c-8059-8dddc494ba7f", "type": "concept", "title": "Expression options"}, {"id": "b7877d7e-ead5-4789-99a9-31feb79733be", "type": "concept", "title": "Engagement choices"}], "description": "UDL helps remove barriers before students fail."}, {"id": "2df04f2b-3424-4fdb-8461-859c959783ac", "type": "subtopic", "title": "Family and community literacy", "children": [{"id": "a2e2137d-0813-4b44-abbc-c920faf40247", "type": "concept", "title": "Funds of knowledge"}, {"id": "f8b8d789-f7da-4914-ab38-f8eaf98f1fd0", "type": "concept", "title": "Family literacy routines"}, {"id": "78233217-522d-45a6-9d6d-0dd8437bf768", "type": "concept", "title": "Community texts"}], "description": "Families and communities are partners in language and literacy development."}]}, {"id": "87aa4577-7b3d-4828-8b38-01f0c7ecadfc", "type": "topic", "title": "Disciplinary, digital, and media literacy", "description": "Extend language arts into content-area reading, digital composition, media evaluation, and responsible technology use. Core emphasis: Content-area literacy, disciplinary reading, digital texts, multimodal composing, media literacy, source evaluation, and AI-aware literacy.", "children": [{"id": "a7a47418-6592-428b-b56f-e048144b2af1", "type": "subtopic", "title": "Disciplinary literacy", "children": [{"id": "d6ea5551-5a64-4e1c-82a1-95511bf4347c", "type": "concept", "title": "Text features by discipline"}, {"id": "d3c6b0e3-3e69-4929-aa94-630bfe2b83a1", "type": "concept", "title": "Evidence norms"}, {"id": "efce349f-fca5-4d99-9163-5247f8dc26ff", "type": "concept", "title": "Vocabulary in content areas"}], "description": "Reading like a scientist, historian, or mathematician requires different habits."}, {"id": "c0279de8-a26c-43dd-a4ac-15bd256dd83f", "type": "subtopic", "title": "Digital reading and composing", "children": [{"id": "d92d1bdd-a11c-43af-a8da-96773ffd14b3", "type": "concept", "title": "Hyperlinks"}, {"id": "0db64e01-564e-4474-bf1f-33bfec1e32aa", "type": "concept", "title": "Multimodal composition"}, {"id": "1e1eeef3-3501-40a8-8eb2-7e49a9523607", "type": "concept", "title": "Accessibility features"}], "description": "Students need strategies for nonlinear, multimedia, and screen-based texts."}, {"id": "d18a870e-d11d-4cee-a33b-9f1a45f72ba0", "type": "subtopic", "title": "Media and source evaluation", "children": [{"id": "fb671cbd-a982-4961-b622-262d6b04a66d", "type": "concept", "title": "Lateral reading"}, {"id": "4b637ef3-ebdb-4699-b7a7-d040a601b1dd", "type": "concept", "title": "Author/source checks"}, {"id": "44d5c2ea-482c-4fe7-80a7-4554758eb643", "type": "concept", "title": "Misinformation"}], "description": "Language arts now includes evaluating credibility and bias."}, {"id": "4322577e-43ab-4d6c-b1a2-c2c49728b463", "type": "subtopic", "title": "AI-aware literacy", "children": [{"id": "7a4c157d-b5fe-4286-b66d-61ddf3afad22", "type": "concept", "title": "Prompting basics"}, {"id": "8d4655db-5318-4d8a-8495-ca1d736a0996", "type": "concept", "title": "Authorship and citation"}, {"id": "32d0b293-6bd9-4c54-a450-b529f6617e3a", "type": "concept", "title": "Human judgment"}], "description": "Teachers should help students use emerging tools ethically and thoughtfully."}]}], "dbBacked": true}$trlajson$::jsonb,
