update public.learning_paths
set
  title = 'Teaching Reading and Language Arts',
  goal = 'Teaching Reading and Language Arts',
  summary = 'This course prepares elementary teacher candidates to plan, teach, assess, and adapt reading, writing, speaking, listening, and language instruction. This version combines practical classroom methods with the science of reading, culturally responsive pedagogy, inclusive assessment, and real instructional decision-making.',
  data = $trlajson${"slug": "teaching-reading-and-language-arts", "title": "Teaching Reading and Language Arts", "description": "This course prepares elementary teacher candidates to plan, teach, assess, and adapt reading, writing, speaking, listening, and language instruction. This version combines practical classroom methods with the science of reading, culturally responsive pedagogy, inclusive assessment, and real instructional decision-making.", "topics": [{"id": "f1d2dd46-c04e-4815-aa98-63f3de38723d", "type": "topic", "title": "Evidence-informed literacy frameworks", "description": "Reframe classroom literacy instruction around evidence, developmental progression, teacher judgment, and the useful parts of balanced literacy when aligned with reading science. Core emphasis: Balanced literacy, structured literacy, gradual release, language-rich instruction, explicit teaching, and authentic literacy practice.", "children": [{"id": "83899471-74c6-49db-91a4-8058337ec83a", "type": "subtopic", "title": "Balanced literacy in context", "children": [{"id": "ff89fc14-75e1-4b51-82b9-27c2d423cc21", "type": "concept", "title": "Read-alouds and shared reading"}, {"id": "2d4412b6-d378-4850-8089-5eb3523fafa6", "type": "concept", "title": "Independent reading"}, {"id": "5bbcb77a-1e07-4683-b39c-1cbf016d3555", "type": "concept", "title": "Limits of cueing-based approaches"}], "description": "Students learn what balanced literacy tried to solve and where it needs revision."}, {"id": "6ccd86d3-bf21-48e1-902c-480936373430", "type": "subtopic", "title": "Structured literacy alignment", "children": [{"id": "29dbb270-e709-46a9-979e-39d01747a714", "type": "concept", "title": "Systematic scope and sequence"}, {"id": "9e34cfcc-3fe0-42e2-8093-b5bb77e4ddc7", "type": "concept", "title": "Cumulative review"}, {"id": "2258636f-ba36-4503-9776-544574507413", "type": "concept", "title": "Explicit modeling"}], "description": "A strong practice includes explicit, systematic language instruction."}, {"id": "70a0455d-2f3a-4f8c-839c-d009d0b986f6", "type": "subtopic", "title": "Gradual release of responsibility", "children": [{"id": "4164bb61-db4f-4236-bfc8-e224037c245d", "type": "concept", "title": "I do, we do, you do"}, {"id": "cf053fb2-b740-4024-84c9-902f098231bd", "type": "concept", "title": "Guided practice"}, {"id": "1491757c-c00e-4a66-ad52-4e56cba4938a", "type": "concept", "title": "Independent transfer"}], "description": "Teachers plan how responsibility moves from teacher modeling to student independence."}, {"id": "bf021557-f5f4-4826-b245-83d52d6e0beb", "type": "subtopic", "title": "Integrated literacy block design", "children": [{"id": "afa3d978-2fa4-4792-802d-208bf2e7b22d", "type": "concept", "title": "Mini-lessons"}, {"id": "f60bfe30-4672-4927-aab5-e52942b3043f", "type": "concept", "title": "Centers and routines"}, {"id": "2dec1760-8799-4c73-9386-7e26d6e8da3e", "type": "concept", "title": "Coherent daily schedule"}], "description": "A strong literacy block connects decoding, language, comprehension, writing, and discussion."}]}, {"id": "74d7d9e4-4300-4d7e-81b3-b5c1a0201400", "type": "topic", "title": "Science of reading and foundational skills", "description": "Ground reading methods in how children learn to map spoken language to print. Core emphasis: Phonological awareness, phonemic awareness, phonics, decoding, orthographic mapping, fluency, vocabulary, and comprehension foundations.", "children": [{"id": "4594ed75-5f63-42bd-b507-c11d1d777c75", "type": "subtopic", "title": "Phonological and phonemic awareness", "children": [{"id": "3b7a37a2-411f-4637-8fd6-a4ca311f3ac0", "type": "concept", "title": "Rhyme and syllables"}, {"id": "5c518fcd-5df8-4978-82b8-d575231457a8", "type": "concept", "title": "Phoneme isolation"}, {"id": "7d0ad7db-19be-4539-9cfd-8ea550b2b6bf", "type": "concept", "title": "Blending and segmenting"}], "description": "Students learn why hearing and manipulating sounds supports decoding."}, {"id": "be39070f-82c4-48ea-b0dd-9e296401a824", "type": "subtopic", "title": "Phonics and decoding", "children": [{"id": "56194772-9640-41de-b177-1674de8b4610", "type": "concept", "title": "Letter-sound correspondences"}, {"id": "860c58fa-8de2-4589-9160-1ff9380ba391", "type": "concept", "title": "Blending routines"}, {"id": "84b7f8de-8c25-4f69-b653-70c759431c00", "type": "concept", "title": "Syllable patterns"}], "description": "Explicit phonics helps students connect graphemes to phonemes and read unfamiliar words."}, {"id": "49506d1f-f970-4e54-b2eb-a858c97566c7", "type": "subtopic", "title": "Orthographic mapping", "children": [{"id": "e58572ff-f3ed-4d2c-8510-e9fb4fd1eb9a", "type": "concept", "title": "Phoneme-grapheme mapping"}, {"id": "bc9a9b14-ab3a-4e83-ba19-c76d11af8d28", "type": "concept", "title": "High-frequency words"}, {"id": "a6466c93-8186-438c-91e8-9d1a8dc4cf48", "type": "concept", "title": "Irregular word instruction"}], "description": "Students learn how words become instantly recognizable."}, {"id": "427e78c6-88b2-4674-98b3-cbea4c260e91", "type": "subtopic", "title": "Fluency foundations", "children": [{"id": "502ee621-1f8b-442b-8a15-7ca92ad467ac", "type": "concept", "title": "Accuracy"}, {"id": "6bae370f-8d1a-4a15-ae11-746429a5146e", "type": "concept", "title": "Rate"}, {"id": "a3a9f4ae-edc9-40a2-9961-5a3a12b119af", "type": "concept", "title": "Prosody"}], "description": "Fluency links accurate word reading to comprehension."}]}, {"id": "f13c32a7-87e6-452a-b846-e6f9bc026230", "type": "topic", "title": "Whole-group and small-group reading instruction", "description": "Teach candidates to choose the right instructional format for the purpose, evidence, and students in front of them. Core emphasis: Whole-group lessons, small-group instruction, flexible grouping, mini-lessons, decodable/complex texts, and responsive teaching.", "children": [{"id": "47fd304b-e47c-48e3-81c7-aff905e84774", "type": "subtopic", "title": "Whole-group instruction", "children": [{"id": "93d6b99c-bedb-404f-b10b-1e278b7b0252", "type": "concept", "title": "Read-alouds"}, {"id": "ab0b9553-1703-4aa4-8ac5-633e6dabe59d", "type": "concept", "title": "Shared reading"}, {"id": "e22ac185-4926-4ccc-9228-5bdf5910d439", "type": "concept", "title": "Vocabulary and comprehension modeling"}], "description": "Whole group is useful for shared knowledge, modeling, and community language."}, {"id": "f5ede3b8-505e-4078-b970-8f7e3e78c858", "type": "subtopic", "title": "Small-group instruction", "children": [{"id": "9c00a8fd-4c15-49c2-b639-284e74f82314", "type": "concept", "title": "Flexible grouping"}, {"id": "4dc8d3f0-abe2-41b4-ba07-2b9bfec77ad7", "type": "concept", "title": "Skill-based groups"}, {"id": "821d92fb-44fc-4ffc-8a47-fdede1559e7e", "type": "concept", "title": "Teacher observation"}], "description": "Small groups target specific needs with tighter feedback."}, {"id": "e70ee938-2d42-425d-835b-7f7eb0f8fd31", "type": "subtopic", "title": "Text selection by purpose", "children": [{"id": "a4c158b1-99fe-44df-9798-5e25765b94fb", "type": "concept", "title": "Decodable texts"}, {"id": "9738508a-403e-4dc6-ad82-7413c0d4eb7f", "type": "concept", "title": "Complex read-alouds"}, {"id": "13a40004-90b2-4b12-9b37-5566d25b5d84", "type": "concept", "title": "Student-choice texts"}], "description": "Different texts serve different instructional jobs."}, {"id": "f7729a77-26f5-4408-b287-ae1f4ccece41", "type": "subtopic", "title": "Responsive teaching moves", "children": [{"id": "468ee9d2-e440-4706-b544-6ff65195e844", "type": "concept", "title": "Prompting"}, {"id": "2f441345-0cf8-4eec-9b12-69306aced67b", "type": "concept", "title": "Corrective feedback"}, {"id": "66f67d7e-22a5-44f4-add4-53ea039813b4", "type": "concept", "title": "Checks for understanding"}], "description": "Teachers adjust instruction based on student responses."}]}, {"id": "593fd735-7c60-4b85-aaaa-4ca7ee9fba6b", "type": "topic", "title": "Guided reading, decodable text, and text-based comprehension", "description": "Update guided reading practice so it supports decoding, knowledge, vocabulary, and comprehension rather than guessing from context. Core emphasis: Guided reading, decodable readers, close reading, text-dependent questions, comprehension strategies, and knowledge-building text sets.", "children": [{"id": "7d54c0d6-602d-4eeb-bbbd-0a6564c5757d", "type": "subtopic", "title": "Guided reading revisited", "children": [{"id": "ce9a6a4a-d37f-424d-9f5b-a0acd02b6747", "type": "concept", "title": "Purpose and limits"}, {"id": "bb6ef5f4-be7d-4ffb-9fcb-d174ba8303e2", "type": "concept", "title": "Book introductions"}, {"id": "726a929d-3efb-4260-b0c9-b5edb9d22fb1", "type": "concept", "title": "Teacher prompts"}], "description": "Students learn how to use guided reading selectively and evidence-consciously."}, {"id": "63e7bedc-9c15-40a3-83ed-5ef3ea74e6f8", "type": "subtopic", "title": "Decodable text routines", "children": [{"id": "e387d908-8238-4abb-9756-cfeee12825e3", "type": "concept", "title": "Pattern alignment"}, {"id": "9076f346-dc6e-4452-89e0-c80d7c27c569", "type": "concept", "title": "Accuracy practice"}, {"id": "8113afd2-3dab-4131-ad93-f6be4bcf13db", "type": "concept", "title": "Connected text reading"}], "description": "Decodable texts give beginning readers practice applying taught patterns."}, {"id": "9d557da3-3911-4d9c-b0e4-0c9277f37d2c", "type": "subtopic", "title": "Comprehension strategy instruction", "children": [{"id": "86bff45b-85cd-41fd-9b71-08e2ac9b0510", "type": "concept", "title": "Questioning"}, {"id": "20aa18f2-3473-418f-8b46-dfd51f9ebd1f", "type": "concept", "title": "Summarizing"}, {"id": "5aec602c-03d4-48fc-bc76-54c6a0d59733", "type": "concept", "title": "Inference"}], "description": "Strategies help students monitor and repair meaning."}, {"id": "f0615478-3699-40d1-bf43-d34db3184507", "type": "subtopic", "title": "Knowledge-building text sets", "children": [{"id": "e5c6d592-cf99-49ef-af22-b9bebdc01757", "type": "concept", "title": "Topic coherence"}, {"id": "948f626e-bcbc-48d8-acdf-5748006acab2", "type": "concept", "title": "Vocabulary networks"}, {"id": "73407429-3a43-4786-b4b5-6acd88eb3596", "type": "concept", "title": "Text sequencing"}], "description": "Comprehension grows when students build background knowledge across texts."}]}, {"id": "bd386a3d-8dea-442d-bc5d-df61fba416eb", "type": "topic", "title": "The writing process and writers' workshop", "description": "Teach writing as a developmental, recursive process supported by explicit instruction, mentor texts, conferencing, and feedback. Core emphasis: Prewriting, drafting, revising, editing, publishing, writer identity, mentor texts, conferencing, and process-based routines.", "children": [{"id": "cc4ffeab-3b10-48f2-92a0-70ec1ce4eac4", "type": "subtopic", "title": "Writing process", "children": [{"id": "5a438e0f-8ce3-4a42-951e-de57964e4915", "type": "concept", "title": "Prewriting"}, {"id": "50b2aabb-da26-49ff-9986-36aeb1ea8d42", "type": "concept", "title": "Drafting"}, {"id": "2a2a46a4-357a-49cc-877f-6650ffddc12a", "type": "concept", "title": "Revision and editing"}], "description": "Students learn to teach writing as planning, composing, revising, and sharing."}, {"id": "e6519c8f-3a99-419a-9844-ed1184e72d81", "type": "subtopic", "title": "Writers' workshop routines", "children": [{"id": "87e7cb02-934a-4f45-b63a-f55328fd11a0", "type": "concept", "title": "Mini-lessons"}, {"id": "e37d9701-fd25-44b2-b01b-214a32baaa03", "type": "concept", "title": "Independent writing"}, {"id": "386ed4b6-05f0-4822-9ed4-c57cad2bfd79", "type": "concept", "title": "Author's chair"}], "description": "Workshop structures time, agency, and teacher support."}, {"id": "8aeacbba-511e-4dc1-a8b3-baea77225257", "type": "subtopic", "title": "Writing conferences", "children": [{"id": "5c1ce30c-5bed-4ee8-8c65-6cd650815b6d", "type": "concept", "title": "Noticing strengths"}, {"id": "5b1484e6-38c9-44ba-a89c-5df43bce5c87", "type": "concept", "title": "Teaching points"}, {"id": "3a5872db-3fa1-44a4-8f4d-02200a67e0d4", "type": "concept", "title": "Goal setting"}], "description": "Conferences make feedback individualized and actionable."}, {"id": "698689af-e06c-43d2-806f-643bd90c57a9", "type": "subtopic", "title": "Mentor texts", "children": [{"id": "2034eea5-115e-44f5-adc7-ee24c2e48fb3", "type": "concept", "title": "Sentence craft"}, {"id": "1ae42f73-bf5a-4829-919b-cca6a3d7514e", "type": "concept", "title": "Structure imitation"}, {"id": "2ba51969-fdf3-4a2a-8d6c-666e7d99fe97", "type": "concept", "title": "Author study"}], "description": "Published texts show craft moves students can try."}]}, {"id": "1793b1b0-8775-46dc-8d48-19bbd20e21bf", "type": "topic", "title": "Genre study: narrative, informational, and opinion writing", "description": "Help students teach how genre shapes reading, writing, structure, evidence, and audience. Core emphasis: Narrative, informational, opinion/argument, genre features, mentor texts, rubrics, and cross-curricular writing.", "children": [{"id": "fb8f82f8-11e9-42c0-9a9b-339eecdc4e1d", "type": "subtopic", "title": "Narrative writing", "children": [{"id": "6f7c32ef-697a-43bc-a210-407c4f296e92", "type": "concept", "title": "Story structure"}, {"id": "168b5b5e-724f-4bb7-be71-33884ae97bab", "type": "concept", "title": "Dialogue and description"}, {"id": "39f4f85f-dab8-41a1-a9a2-a98563b8cddc", "type": "concept", "title": "Personal narrative"}], "description": "Narratives teach sequence, character, event, voice, and elaboration."}, {"id": "41508629-3e33-4d2f-a37c-1b3a304cd7a4", "type": "subtopic", "title": "Informational writing", "children": [{"id": "db75fd96-1913-46b5-a81b-78dec16c8d2c", "type": "concept", "title": "Main ideas"}, {"id": "ee8080f7-ce2c-474d-8394-d8077f92f173", "type": "concept", "title": "Text features"}, {"id": "eaeb2402-46ae-41dd-8c65-4415243b60c1", "type": "concept", "title": "Domain vocabulary"}], "description": "Informational writing builds explanation and knowledge communication."}, {"id": "a710b642-83d0-40e7-80cb-e2f2e6f8f274", "type": "subtopic", "title": "Opinion and argument writing", "children": [{"id": "91703c10-652b-41bf-99b7-3b8d5e362068", "type": "concept", "title": "Claims"}, {"id": "d4362337-dd10-4a7c-ac7c-f2407a3867fc", "type": "concept", "title": "Reasons and evidence"}, {"id": "e65dbfc1-cadc-4dfa-8082-af02be10cdfa", "type": "concept", "title": "Counterargument readiness"}], "description": "Opinion writing introduces claims, reasons, evidence, and audience."}, {"id": "a07dac23-9a2e-4f19-977c-ef43ee00675a", "type": "subtopic", "title": "Genre-based assessment", "children": [{"id": "f5404145-f236-4007-9b4f-1cd4ca2757aa", "type": "concept", "title": "Trait rubrics"}, {"id": "4636bc2b-b051-4cdf-9f14-e57cd4e2dab7", "type": "concept", "title": "Anchor papers"}, {"id": "b84d36b8-2032-4f6d-bf0f-c03ec8c37455", "type": "concept", "title": "Revision goals"}], "description": "Genre expectations should be visible in rubrics and feedback."}]}, {"id": "321ea302-5928-4bca-8884-a978c8b195d2", "type": "topic", "title": "Grammar, syntax, and conventions instruction", "description": "Teach conventions as tools for meaning, clarity, voice, and access rather than isolated correction. Core emphasis: Sentence structure, grammar, punctuation, capitalization, usage, syntax, morphology, and editing routines.", "children": [{"id": "d47e21e6-b32f-4b5f-a744-88b46b9f8afe", "type": "subtopic", "title": "Sentence-level instruction", "children": [{"id": "a4c4099d-640b-40e8-b9b4-1212c9870398", "type": "concept", "title": "Subjects and predicates"}, {"id": "0e8ab033-81c1-48e4-815c-2414908dfb49", "type": "concept", "title": "Sentence combining"}, {"id": "519d228e-8063-4460-8ca4-13501316d8ae", "type": "concept", "title": "Complex sentences"}], "description": "Students learn grammar by studying how sentences make meaning."}, {"id": "2b2c6323-7be0-4c52-9c34-813eb480b258", "type": "subtopic", "title": "Conventions in context", "children": [{"id": "2226ee26-7c17-4aec-9ae8-ffc281d55ac5", "type": "concept", "title": "Punctuation for meaning"}, {"id": "d1f79ae0-e297-4ad8-95e6-7ef8b4acfc57", "type": "concept", "title": "Capitalization"}, {"id": "eb2a6aca-a432-4824-9843-505b75e73a95", "type": "concept", "title": "Editing checklists"}], "description": "Conventions instruction works best inside reading and writing."}, {"id": "ae49df68-ae32-4065-9140-a722f792dc64", "type": "subtopic", "title": "Syntax and comprehension", "children": [{"id": "44dc9955-39cb-418e-9c00-3162dba3ea81", "type": "concept", "title": "Clause structures"}, {"id": "fdd01c26-3957-4d47-8e45-15d83925623c", "type": "concept", "title": "Connectives"}, {"id": "f25ee8ae-10d2-474e-aa8c-269d0d5266d8", "type": "concept", "title": "Deconstructing sentences"}], "description": "Complex syntax affects reading comprehension and academic language."}, {"id": "a709fe7b-a2a1-4fde-819e-dce3fdcf58a3", "type": "subtopic", "title": "Language variation and standard English", "children": [{"id": "3ebfb781-14a0-42e9-9d90-75daab99c322", "type": "concept", "title": "Code-switching/code-meshing"}, {"id": "ce665d2d-22ec-4237-9e26-9bcece606770", "type": "concept", "title": "Dialect awareness"}, {"id": "63a5067d-da37-45eb-b8d5-b37601ab63fe", "type": "concept", "title": "Audience and purpose"}], "description": "Teachers honor dialects while teaching access to academic conventions."}]}, {"id": "f4ffe9b5-f39b-4b70-bc6b-82d308264db9", "type": "topic", "title": "Word study, spelling, and vocabulary development", "description": "Connect spelling, morphology, phonics, and vocabulary into a coherent word-learning system. Core emphasis: Developmental spelling, morphology, etymology, academic vocabulary, semantic networks, and word-learning routines.", "children": [{"id": "e6658141-b275-4e99-aa29-1a0b76515069", "type": "subtopic", "title": "Developmental spelling", "children": [{"id": "52faf234-7a26-4fa6-a9b2-cc2b377378dc", "type": "concept", "title": "Invented spelling analysis"}, {"id": "9d1e2a10-d758-4269-9b57-cb5dd4825ff4", "type": "concept", "title": "Word sorts"}, {"id": "5b4c2b5a-eee1-4622-9a90-22d064651155", "type": "concept", "title": "Spelling stages"}], "description": "Spelling reveals what students understand about sounds and patterns."}, {"id": "853b3011-e1ac-4b48-9791-c18f47462773", "type": "subtopic", "title": "Morphology", "children": [{"id": "a6a3805c-3307-40da-81d8-079d5cfb062d", "type": "concept", "title": "Prefixes"}, {"id": "79ab8ddc-0d24-4ca4-94d6-289d004742ca", "type": "concept", "title": "Suffixes"}, {"id": "09f80804-13ef-4ef7-a832-f7d2f615af28", "type": "concept", "title": "Roots and bases"}], "description": "Morphemes help students decode, spell, and understand complex words."}, {"id": "2852ee08-8ab4-4538-9565-a4121d69cce5", "type": "subtopic", "title": "Vocabulary instruction", "children": [{"id": "d34e3f97-88a0-4513-88b0-a0719d5d75e3", "type": "concept", "title": "Tiered vocabulary"}, {"id": "6b8d422f-bf06-46f1-bd52-167a2c560dbb", "type": "concept", "title": "Student-friendly definitions"}, {"id": "979e214f-9331-4e40-a463-c877c8a7eb43", "type": "concept", "title": "Multiple encounters"}], "description": "Vocabulary grows through explicit teaching and rich exposure."}, {"id": "e414c3a6-99f7-49b9-aed5-98f9916167cb", "type": "subtopic", "title": "Word consciousness", "children": [{"id": "52c6adc5-558f-4fd7-8baa-496d28c45bc5", "type": "concept", "title": "Etymology"}, {"id": "25eb88e7-6711-49b1-8e5d-aedad12d7dc9", "type": "concept", "title": "Word families"}, {"id": "536852de-10e3-4d48-a39e-afdd96deb71c", "type": "concept", "title": "Context clues"}], "description": "Students become curious about how words work."}]}, {"id": "8b447cc1-0fde-43f3-bb2f-58d7749bb0c9", "type": "topic", "title": "Speaking, listening, and oral language", "description": "Recognize oral language as the foundation for reading comprehension, writing, vocabulary, and classroom participation. Core emphasis: Academic talk, listening routines, discussion, storytelling, language development, presentation, and collaborative conversation.