lly."}]}, {"id": "2ae60bce-0442-4758-bc7f-29f37243c944", "type": "topic", "title": "Literacy assessment", "description": "Prepare teachers to use screening, diagnostic, formative, summative, and performance assessments responsibly. Core emphasis: Screeners, diagnostics, running records, phonics inventories, writing rubrics, comprehension checks, validity, fairness, and data use.", "children": [{"id": "e51e1486-db11-4b20-b496-25bda8590be1", "type": "subtopic", "title": "Assessment purposes", "children": [{"id": "55aae044-06ec-454e-8532-cbe782d4c60a", "type": "concept", "title": "Screening"}, {"id": "28e37f9f-450d-4b14-9393-ff80d4679580", "type": "concept", "title": "Diagnosis"}, {"id": "457db925-fbc4-4777-a440-a8a29cbe6750", "type": "concept", "title": "Progress monitoring"}], "description": "Different assessments answer different instructional questions."}, {"id": "73e60dcf-9b82-4df9-b42d-076bad01e8d6", "type": "subtopic", "title": "Foundational skill assessment", "children": [{"id": "ae144fad-6bdd-4ed1-baff-cf736e563e1c", "type": "concept", "title": "Phonemic awareness checks"}, {"id": "e97f552a-30e5-4c81-93b9-40057e1b2b24", "type": "concept", "title": "Phonics inventories"}, {"id": "3ab79350-eb06-40c5-ba92-1d90a5a6c5b5", "type": "concept", "title": "Oral reading fluency"}], "description": "Teachers need precise data on decoding and word-reading skills."}, {"id": "9e46364d-7b06-49af-8a43-5729e9ae4354", "type": "subtopic", "title": "Comprehension and writing assessment", "children": [{"id": "7b61151d-1b8f-44bc-a2c7-3692a8d136c7", "type": "concept", "title": "Retellings"}, {"id": "b33aa1d9-0983-4f20-a9e4-98a015598466", "type": "concept", "title": "Written responses"}, {"id": "048b9630-85bd-4a9e-b1de-fb2392e5ea02", "type": "concept", "title": "Writing rubrics"}], "description": "Higher-level literacy needs multiple forms of evidence."}, {"id": "37358f31-2838-4158-a07f-1d321d84e8c5", "type": "subtopic", "title": "Fairness and interpretation", "children": [{"id": "fbae5